  "requirements": [
    {
      "id": "F-01",
      "text": "The system shall ensure compliance with data protection regulations when handling student attendance data.",
      "quality_axes": ["Responsibility"],
      "derived_from": ["RES-01"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-02",
      "text": "The system shall implement a hybrid adaptive logging system that logs critical events in real-time and non-critical events asynchronously with integrity checks.",
      "quality_axes": ["Safety|Trustworthiness|Efficiency"],
      "derived_from": ["SAF-05", "TRU-03"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-03",
      "text": "The system shall generate attendance reports that adhere to compliance standards while optimizing performance using energy-efficient formats.",
      "quality_axes": ["Efficiency|Sustainability|Responsibility"],
      "derived_from": ["EFF-03", "GRN-04"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-04",
      "text": "The system shall support real-time data processing to provide updates within 2 seconds of input.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-01"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-05",
      "text": "The system shall support at least 500 concurrent users without performance degradation.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-02"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-06",
      "text": "The system shall allow students to view their attendance records with a response time under 3 seconds after successful authentication.",
      "quality_axes": ["Efficiency|Trustworthiness"],
      "derived_from": ["EFF-05", "TRU-04"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-07",
      "text": "The system shall maintain historical attendance data for a minimum of 5 years with optimized storage and compliance.",
      "quality_axes": ["Efficiency|Responsibility"],
      "derived_from": ["EFF-04", "RES-07"],
      "kaos_level": "operational",
      "parent": null
    }
  ],
